// Entrada: un ítem por archivo leído de /data/proyecto (config/*.json, schemas/*.json, prompts/*.md).
const archivos = {};
const entrada = $input.all();
for (let i = 0; i < entrada.length; i++) {
  const bin = entrada[i].binary && entrada[i].binary.data;
  if (!bin) continue;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  archivos[bin.fileName] = buf.toString('utf8');
}
for (const nombre of ['parametros.json', 'fuentes.json', 'caso.schema.json', 'extraccion.md', 'clasificacion.md']) {
  if (!(nombre in archivos)) throw new Error(`Falta el archivo ${nombre} en /data/proyecto. Revisa los volúmenes de docker-compose.yml.`);
}

const parametros = JSON.parse(archivos['parametros.json']);
parametros.max_articulos_por_ejecucion = 5; // PRUEBA: solo 5 artículos
const PROVEEDOR = 'anthropic'; // proveedor de IA con el que se generó este workflow
parametros.proveedor_ia = PROVEEDOR;
for (const t of Object.keys(parametros.modelos)) parametros.modelos[t] = parametros.modelos[t][PROVEEDOR];
const fuentes = JSON.parse(archivos['fuentes.json']).fuentes
  .filter(f => f.activa && parametros.idiomas.includes(f.idioma));

// Primera ejecución: ventana ampliada (30 días). La marca se guarda al terminar con éxito.
const sd = $getWorkflowStaticData('global');
const primera = !sd.primera_ejecucion_hecha;

return [{
  json: {
    run_id: 'r-' + Date.now().toString(36),
    inicio_iso: new Date().toISOString(),
    primera_ejecucion: primera,
    ventana_dias: primera ? parametros.ventana_dias_primera_ejecucion : parametros.ventana_dias,
    parametros,
    schema: JSON.parse(archivos['caso.schema.json']),
    prompts: { extraccion: archivos['extraccion.md'], clasificacion: archivos['clasificacion.md'] },
    fuentes,
  },
}];

// Una sola salida con las URLs ya guardadas como casos (la hoja puede estar vacía).
const urls = $input.all().map(i => i.json.url_normalizada).filter(Boolean);
return [{ json: { urls } }];

// Une las URLs de "casos" y de "descartados": un artículo descartado no se vuelve a pagar al día siguiente.
const casos = $('URLs conocidas (casos)').first().json.urls;
const descartadas = $input.all().map(i => i.json.url_normalizada).filter(Boolean);
return [{
  json: {
    n_casos: casos.length,
    n_descartados: descartadas.length,
    urls: [...new Set([...casos, ...descartadas])],
  },
}];

// Un ítem por fuente activa; el nodo RSS Read los procesa de uno en uno (concurrencia 1).
const cfg = $('Cargar configuración').first().json;
return cfg.fuentes.map((f, idx) => ({ json: { ...f, idx } }));

// Convierte los ítems del RSS (de todas las fuentes) en artículos con un formato común.
const MARCAS = /^(utm_|fbclid|gclid|mc_cid|mc_eid|ocid|xtor|cmp|ref$|ref_|source$|spm|igshid)/i;

function quitarHtml(s) {
  return String(s || '')
    .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'").replace(/&hellip;/g, '…')
    .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)))
    .replace(/\s+/g, ' ').trim();
}

// El global URL no existe en el sandbox de los nodos Code de n8n: se analiza la URL con una expresión regular.
function partesUrl(u) {
  const m = String(u || '').trim().match(/^https?:\/\/([^\/?#:]+)(?::\d+)?([^?#]*)(?:\?([^#]*))?/i);
  return m ? { host: m[1].toLowerCase().replace(/^www\./, ''), ruta: m[2] || '', consulta: m[3] || '' } : null;
}

function hostDe(u) {
  const p = partesUrl(u);
  return p ? p.host : '';
}

// Misma noticia con distinto utm_*, www, fragmento o barra final → misma clave.
function normalizarUrl(u) {
  const p = partesUrl(u);
  if (!p) return String(u || '').trim().toLowerCase();
  const params = p.consulta.split('&').filter(x => x && !MARCAS.test(x.split('=')[0])).sort();
  return p.host + p.ruta.replace(/\/+$/, '') + (params.length ? '?' + params.join('&') : '');
}

function fechaIso(v) {
  const t = Date.parse(v || '');
  return isNaN(t) ? null : new Date(t).toISOString();
}

// Hash estable (cyrb53) de la URL normalizada; sirve como id del caso.
function hash(s) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 2654435761);
    h2 = Math.imul(h2 ^ c, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return 'c' + (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}


const salida = [];
const entrada = $input.all();
for (let k = 0; k < entrada.length; k++) {
  const it = entrada[k];
  if (!it.json.link) continue;
  // itemMatching recorre la trazabilidad de ítems hasta la fuente que originó este artículo
  const f = $('Preparar fuentes').itemMatching(k).json;
  const bruto = it.json.contentSnippet || it.json.content || it.json['content:encoded'] || it.json.summary || '';
  salida.push({
    json: {
      fuente: f.nombre,
      tipo_fuente: f.tipo,
      region_fuente: f.region,
      idioma: f.idioma,
      acceso_fuente: f.acceso,
      titular: quitarHtml(it.json.title),
      url: it.json.link.trim(),
      url_normalizada: normalizarUrl(it.json.link),
      fecha_publicacion: fechaIso(it.json.isoDate || it.json.pubDate),
      resumen_feed: quitarHtml(bruto).slice(0, 800),
      origen: 'rss',
    },
  });
}
return salida;

// Salida de error del nodo RSS Read: se registra y el flujo sigue con las demás fuentes.
return $input.all().map((it, k) => {
  const f = $('Preparar fuentes').itemMatching(k).json;
  const err = it.json.error;
  const msg = typeof err === 'string' ? err : (err && (err.message || JSON.stringify(err))) || 'error desconocido';
  return { json: { fuente: f.nombre, feed_url: f.feed_url, error: String(msg).slice(0, 200) } };
});

// Se queda con los artículos publicados dentro de la ventana (7 días; 30 en la primera ejecución).
const cfg = $('Cargar configuración').first().json;
const ahora = Date.now();
const limite = ahora - cfg.ventana_dias * 86400000;
return $input.all()
  .filter(i => i.json.url)
  .filter(i => {
    const t = Date.parse(i.json.fecha_publicacion);
    return !isNaN(t) && t >= limite && t <= ahora + 86400000;
  })
  .map(i => ({ json: i.json }));

// Incluir: titular o resumen del feed contiene alguna palabra clave. Excluir: el TITULAR contiene alguna palabra de exclusión.
const p = $('Cargar configuración').first().json.parametros;
const sensibles = new Set(p.siglas_sensibles_mayusculas || []);
const sinAcentos = s => s.normalize('NFD').replace(/\p{Diacritic}/gu, '');
const escapar = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const LIMITE_I = '(?<![\\p{L}\\p{N}])';
const LIMITE_D = '(?![\\p{L}\\p{N}])';

function construir(term) {
  return sensibles.has(term)
    ? { regex: new RegExp(LIMITE_I + escapar(term) + LIMITE_D, 'u'), literal: true }
    : { regex: new RegExp(LIMITE_I + escapar(sinAcentos(term.toLowerCase())) + LIMITE_D, 'u'), literal: false };
}
const incluir = p.palabras_clave_incluir.map(construir);
const excluir = p.palabras_clave_excluir.map(construir);
const coincide = (lista, texto) => {
  const norm = sinAcentos(texto.toLowerCase());
  return lista.some(k => k.regex.test(k.literal ? texto : norm));
};

return $input.all()
  .filter(i => i.json.url)
  .filter(i => {
    const texto = `${i.json.titular} ${i.json.resumen_feed}`;
    return coincide(incluir, texto) && !coincide(excluir, i.json.titular);
  })
  .map(i => ({ json: i.json }));

// Descarta URLs ya vistas (hojas "casos" y "descartados") y repetidas dentro de esta misma ejecución.
const conocidas = new Set($('URLs conocidas (descartados)').first().json.urls);

const MARCAS = /^(utm_|fbclid|gclid|mc_cid|mc_eid|ocid|xtor|cmp|ref$|ref_|source$|spm|igshid)/i;

function quitarHtml(s) {
  return String(s || '')
    .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'").replace(/&hellip;/g, '…')
    .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)))
    .replace(/\s+/g, ' ').trim();
}

// El global URL no existe en el sandbox de los nodos Code de n8n: se analiza la URL con una expresión regular.
function partesUrl(u) {
  const m = String(u || '').trim().match(/^https?:\/\/([^\/?#:]+)(?::\d+)?([^?#]*)(?:\?([^#]*))?/i);
  return m ? { host: m[1].toLowerCase().replace(/^www\./, ''), ruta: m[2] || '', consulta: m[3] || '' } : null;
}

function hostDe(u) {
  const p = partesUrl(u);
  return p ? p.host : '';
}

// Misma noticia con distinto utm_*, www, fragmento o barra final → misma clave.
function normalizarUrl(u) {
  const p = partesUrl(u);
  if (!p) return String(u || '').trim().toLowerCase();
  const params = p.consulta.split('&').filter(x => x && !MARCAS.test(x.split('=')[0])).sort();
  return p.host + p.ruta.replace(/\/+$/, '') + (params.length ? '?' + params.join('&') : '');
}

function fechaIso(v) {
  const t = Date.parse(v || '');
  return isNaN(t) ? null : new Date(t).toISOString();
}

// Hash estable (cyrb53) de la URL normalizada; sirve como id del caso.
function hash(s) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 2654435761);
    h2 = Math.imul(h2 ^ c, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return 'c' + (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}


const vistas = new Set();
return $input.all()
  .filter(i => i.json.url)
  .sort((a, b) => Date.parse(b.json.fecha_publicacion) - Date.parse(a.json.fecha_publicacion))
  .filter(i => {
    const u = i.json.url_normalizada;
    if (conocidas.has(u) || vistas.has(u)) return false;
    vistas.add(u);
    return true;
  })
  .map(i => ({ json: { ...i.json, id: hash(i.json.url_normalizada) } }));

// Tope diario de artículos para controlar coste. Los más recientes van primero; el resto se verá en las siguientes ejecuciones.
const max = $('Cargar configuración').first().json.parametros.max_articulos_por_ejecucion;
const items = $input.all().filter(i => i.json.url);
if (items.length === 0) return [{ json: { vacio: true } }]; // marca para que el flujo pase directo al registro
return items.slice(0, max).map(i => ({ json: i.json }));

// Convierte el HTML descargado en texto limpio. Si hay paywall, error o poco texto: solo titular + resumen y acceso "parcial".
const p = $('Cargar configuración').first().json.parametros;
const MIN = p.texto_minimo_caracteres;
const MAX = p.texto_maximo_caracteres;
const PAYWALL = /suscr[ií]bete para|solo para suscriptores|contenido exclusivo para|inicia sesi[oó]n para (seguir|continuar|leer)|subscribe to (continue|read)|already a subscriber|sign in to (continue|read)|create a free account to (continue|read)/i;

const ENTIDADES = { nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", hellip: '…', mdash: '—', ndash: '–', laquo: '«', raquo: '»', iexcl: '¡', iquest: '¿', aacute: 'á', eacute: 'é', iacute: 'í', oacute: 'ó', uacute: 'ú', ntilde: 'ñ', Aacute: 'Á', Eacute: 'É', Iacute: 'Í', Oacute: 'Ó', Uacute: 'Ú', Ntilde: 'Ñ', uuml: 'ü', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“' };
const decodificar = s => s
  .replace(/&#x([0-9a-f]+);/gi, (m, h) => String.fromCharCode(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)))
  .replace(/&([a-zA-Z]+);/g, (m, n) => (n in ENTIDADES ? ENTIDADES[n] : m));
const limpiar = s => decodificar(s.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();

function textoDeHtml(html) {
  let b = (html.match(/<article[\s\S]*<\/article>/i) || html.match(/<main[\s\S]*<\/main>/i) || [html])[0];
  b = b.replace(/<(script|style|nav|aside|footer|header|form|figure|figcaption|svg|noscript|iframe|button)[\s\S]*?<\/\1>/gi, ' ');
  const partes = [];
  const vistos = new Set();
  for (const m of b.matchAll(/<(p|h2|h3)[^>]*>([\s\S]*?)<\/\1>/gi)) {
    const t = limpiar(m[2]);
    const minimo = m[1].toLowerCase() === 'p' ? 40 : 10;
    if (t.length >= minimo && !vistos.has(t)) { vistos.add(t); partes.push(t); }
  }
  return partes.join('\n');
}

return $input.all().map((it, k) => {
  const base = $('Limitar lote diario').itemMatching(k).json;
  const codigo = it.json.statusCode;
  const cuerpo = typeof it.json.data === 'string' ? it.json.data : it.json.body; // el nodo HTTP devuelve el HTML en 'data'
  const html = typeof cuerpo === 'string' ? cuerpo.slice(0, 1500000) : '';
  const ok = !it.json.error && codigo >= 200 && codigo < 300 && html.length > 0;
  let texto = ok ? textoDeHtml(html) : '';
  let motivo = null;
  if (!ok) motivo = it.json.error ? 'error de descarga' : `HTTP ${codigo || 'sin respuesta'}`;
  else if (texto.length < MIN) motivo = 'texto demasiado corto';
  else if (PAYWALL.test(html) && texto.length < MIN * 3) motivo = 'paywall';

  const parcial = motivo !== null;
  if (parcial) texto = `${base.titular}\n${base.resumen_feed}`.trim();
  return {
    json: {
      ...base,
      acceso: parcial ? 'parcial' : 'completo',
      motivo_acceso_parcial: motivo,
      texto: texto.slice(0, MAX),
      texto_chars: texto.length,
    },
  };
});

// Monta el mensaje de sistema y el de usuario a partir del archivo prompts/extraccion.md
const cfg = $('Cargar configuración').first().json;

function partir(md) {
  const limpio = md.replace(/<!--[\s\S]*?-->/g, '');
  const iSys = limpio.indexOf('## SYSTEM');
  const iUsr = limpio.indexOf('## USER');
  if (iSys < 0 || iUsr < 0) throw new Error('El prompt debe tener las secciones "## SYSTEM" y "## USER"');
  return { sistema: limpio.slice(iSys + 9, iUsr).trim(), usuario: limpio.slice(iUsr + 7).trim() };
}
// Una sola pasada: lo que se inserta no se vuelve a interpretar como marcador.
const rellenar = (t, v) => t.replace(/\{\{(\w+)\}\}/g, (m, k) => (v[k] === undefined || v[k] === null ? '' : String(v[k])));

const { sistema, usuario } = partir(cfg.prompts.extraccion);
return $input.all().map(it => {
  const j = it.json;
  const vars = { fuente: j.fuente, fecha_publicacion: (j.fecha_publicacion || "").slice(0, 10), idioma: j.idioma, acceso: j.acceso, titular: j.titular, texto: j.texto };
  return { json: { ...j, prompt_system: sistema, prompt_user: rellenar(usuario, vars) } };
});

// SIMULADO (sin clave de API): imita la respuesta del modelo de IA.
// Posición 1 → responde sin JSON (fuerza el reintento); posición 2 → "no es un caso"; el resto → caso válido.
return $input.all().map((it, k) => {
  const j = it.json;
  const noCaso = { es_caso: false, motivo_no_caso: 'Artículo de opinión sin caso concreto (simulado)', empresa: null, sector: null, pais: null, titulo_caso: null, resumen: null, tecnologia_ia: [], tipo_innovacion: null, madurez: null, resultado: null, metricas: [], confianza: 'baja' };
  const texto = k === 1 ? 'Aquí tienes el análisis en prosa, sin JSON.' : JSON.stringify(k === 2 ? noCaso : { es_caso: true, motivo_no_caso: null, empresa: '(simulado) ' + j.fuente, sector: 'tecnologia_software', pais: 'España', titulo_caso: '(simulado) ' + j.titular.slice(0, 100), resumen: '(simulado) Texto de prueba generado por el mock, no por Claude.', tecnologia_ia: ['IA generativa'], tipo_innovacion: 'producto_servicio', madurez: 'anuncio', resultado: null, metricas: [], confianza: j.acceso === 'parcial' ? 'baja' : 'media' });
  return { json: { content: [{ type: 'text', text: texto }] }, pairedItem: { item: k } };
});

// Lee la respuesta del modelo, la parsea y la valida contra schemas/caso.schema.json → $defs/extraccion.
// Validador mínimo de JSON Schema (sin dependencias) para usar igual en local y dentro de un nodo Code de n8n.
// Soporta: $ref local (#/$defs/...), type (string o lista), enum, required, properties,
// additionalProperties:false, items, minimum, maximum, maxLength, maxItems, oneOf.
// Uso local: node scripts/validar_esquema.js <extraccion|clasificacion|metadatos> <fichero.json>

function resolver(raiz, ref) {
  return ref.replace(/^#\//, '').split('/').reduce((o, k) => o[k], raiz);
}

function tipoDe(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  if (Number.isInteger(v)) return 'integer';
  return typeof v; // string, number, boolean, object
}

function coincideTipo(v, t) {
  const real = tipoDe(v);
  return real === t || (t === 'number' && real === 'integer');
}

function validar(raiz, esquema, valor, ruta, errores) {
  if (esquema.$ref) return validar(raiz, resolver(raiz, esquema.$ref), valor, ruta, errores);

  if (esquema.oneOf) {
    const aciertos = esquema.oneOf.filter(s => {
      const e = [];
      validar(raiz, s, valor, ruta, e);
      return e.length === 0;
    });
    if (aciertos.length !== 1) errores.push(`${ruta}: no cumple exactamente una de las opciones permitidas`);
    return;
  }

  if (esquema.type) {
    const tipos = Array.isArray(esquema.type) ? esquema.type : [esquema.type];
    if (!tipos.some(t => coincideTipo(valor, t))) {
      errores.push(`${ruta}: tipo ${tipoDe(valor)} no permitido (esperado ${tipos.join('|')})`);
      return;
    }
  }
  if (esquema.enum && !esquema.enum.includes(valor)) errores.push(`${ruta}: valor "${valor}" fuera de la lista permitida`);
  if (typeof valor === 'number') {
    if (esquema.minimum !== undefined && valor < esquema.minimum) errores.push(`${ruta}: ${valor} < ${esquema.minimum}`);
    if (esquema.maximum !== undefined && valor > esquema.maximum) errores.push(`${ruta}: ${valor} > ${esquema.maximum}`);
  }
  if (typeof valor === 'string' && esquema.maxLength !== undefined && valor.length > esquema.maxLength) {
    errores.push(`${ruta}: ${valor.length} caracteres (máx. ${esquema.maxLength})`);
  }
  if (Array.isArray(valor)) {
    if (esquema.maxItems !== undefined && valor.length > esquema.maxItems) errores.push(`${ruta}: ${valor.length} elementos (máx. ${esquema.maxItems})`);
    if (esquema.items) valor.forEach((x, i) => validar(raiz, esquema.items, x, `${ruta}[${i}]`, errores));
  }
  if (tipoDe(valor) === 'object') {
    (esquema.required || []).forEach(k => { if (!(k in valor)) errores.push(`${ruta}.${k}: campo obligatorio ausente`); });
    const props = esquema.properties || {};
    for (const k of Object.keys(valor)) {
      if (props[k]) validar(raiz, props[k], valor[k], `${ruta}.${k}`, errores);
      else if (esquema.additionalProperties === false) errores.push(`${ruta}.${k}: campo no permitido`);
    }
  }
}

// Los modelos de IA se pasan de longitud con frecuencia (p. ej. 205 caracteres donde el esquema admite 200). Eso no es un fallo
// de contenido, así que antes de validar se recortan en el sitio los textos y listas que exceden maxLength / maxItems.
function recortarExcesos(raiz, esquema, valor) {
  if (!esquema || valor === null || typeof valor !== 'object') return valor;
  if (esquema.$ref) return recortarExcesos(raiz, resolver(raiz, esquema.$ref), valor);
  if (esquema.oneOf) {
    const rama = esquema.oneOf.find(s => !s.type || coincideTipo(valor, s.type) || s.$ref);
    return rama ? recortarExcesos(raiz, rama, valor) : valor;
  }
  if (Array.isArray(valor)) {
    if (esquema.maxItems !== undefined && valor.length > esquema.maxItems) valor.length = esquema.maxItems;
    valor.forEach((x, i) => {
      if (esquema.items && typeof x === 'string' && esquema.items.maxLength !== undefined && x.length > esquema.items.maxLength) {
        valor[i] = x.slice(0, esquema.items.maxLength - 1) + '…';
      } else if (esquema.items) recortarExcesos(raiz, esquema.items, x);
    });
    return valor;
  }
  const props = esquema.properties || {};
  for (const k of Object.keys(valor)) {
    const s = props[k];
    if (!s) continue;
    const v = valor[k];
    if (typeof v === 'string' && s.maxLength !== undefined && v.length > s.maxLength) valor[k] = v.slice(0, s.maxLength - 1) + '…';
